fn sd_hash(p: vec2<f32>) -> f32 { return fract(sin(dot(p, vec2<f32>(127.1, 311.7))) * 43758.5453); }
fn sd_noise(p: vec2<f32>) -> f32 {
  let i = floor(p);
  let f = fract(p);
  let u = f * f * (3.0 - 2.0 * f);
  return mix(mix(sd_hash(i), sd_hash(i + vec2<f32>(1.0, 0.0)), u.x), mix(sd_hash(i + vec2<f32>(0.0, 1.0)), sd_hash(i + vec2<f32>(1.0, 1.0)), u.x), u.y);
}
// dune ridges drifting on the wind, grain glitter, a warm lamp under the pointer
fn shade(px: Pixel) -> vec4<f32> {
  let wind = px.time * 9.0;
  let p = px.local + vec2<f32>(wind, wind * 0.35);
  let ridge = sin(p.x * 0.012 + 2.4 * sd_noise(p * 0.004) + px.uv.y * 5.0) * 0.5 + 0.5;
  let crest = smoothstep(0.55, 0.9, ridge) - smoothstep(0.9, 1.0, ridge) * 0.6;
  var col = mix(vec3<f32>(0.36, 0.24, 0.13), vec3<f32>(0.62, 0.45, 0.26), px.uv.y);
  col = col + vec3<f32>(0.30, 0.20, 0.09) * crest * 0.55;
  col = col - vec3<f32>(0.10, 0.08, 0.05) * (1.0 - ridge) * 0.35;
  let g = sd_hash(floor(px.local / 1.5) + floor(px.time * 2.0));
  col = col + vec3<f32>(0.9, 0.75, 0.5) * step(0.985, g) * 0.35;
  let streak = sd_noise(vec2<f32>(p.x * 0.02, p.y * 0.4));
  col = col + vec3<f32>(0.08, 0.06, 0.03) * streak * (0.5 + 0.5 * sin(px.time * 0.4));
  let d = distance(px.local, px.pointer);
  col = col + vec3<f32>(1.0, 0.78, 0.45) * exp(-d * d / (2.0 * 170.0 * 170.0)) * 0.32;
  return vec4<f32>(col, 1.0);
}

