// an eight-point star lattice that breathes, gathering gold under the pointer
fn shade(px: Pixel) -> vec4<f32> {
  let p = px.local / 64.0;
  let cell = fract(p) - vec2<f32>(0.5, 0.5);
  let ang = atan2(cell.y, cell.x);
  let r = length(cell);
  let star = abs(cos(ang * 4.0)) * 0.12 + 0.18;
  let line = 1.0 - smoothstep(0.0, 0.02, abs(r - star));
  let pulse = 0.5 + 0.5 * sin(px.time * 0.6 + dot(floor(p), vec2<f32>(1.7, 2.3)));
  var col = mix(vec3<f32>(0.05, 0.06, 0.12), vec3<f32>(0.09, 0.08, 0.16), px.uv.y);
  col = col + vec3<f32>(0.85, 0.66, 0.32) * line * (0.10 + 0.12 * pulse);
  let d = distance(px.local, px.pointer);
  col = col + vec3<f32>(0.9, 0.7, 0.35) * line * exp(-d * d / (2.0 * 160.0 * 160.0)) * 0.5;
  return vec4<f32>(col, 1.0);
}

