// handmade paper: long fibres, mottled tooth, a soft vignette, a lamp that follows the pointer
fn shade(px: Pixel) -> vec4<f32> {
  var col = mix(vec3<f32>(0.95, 0.92, 0.85), vec3<f32>(0.90, 0.86, 0.78), px.uv.y);
  let f1 = pp_noise(vec2<f32>(px.local.x * 0.9, px.local.y * 0.05) + vec2<f32>(11.0, 3.0));
  let f2 = pp_noise(vec2<f32>(px.local.x * 0.04, px.local.y * 0.8) + vec2<f32>(5.0, 17.0));
  col = col - vec3<f32>(0.05, 0.05, 0.06) * smoothstep(0.62, 0.9, f1) * 0.7;
  col = col - vec3<f32>(0.04, 0.045, 0.05) * smoothstep(0.65, 0.9, f2) * 0.7;
  let tooth = pp_noise(px.local / 2.2);
  col = col * (0.96 + 0.06 * tooth);
  let mottle = pp_noise(px.local / 90.0 + vec2<f32>(px.time * 0.01, 0.0));
  col = col - vec3<f32>(0.04, 0.045, 0.05) * mottle;
  let v = px.uv - vec2<f32>(0.5, 0.5);
